`,language:"css"},{name:"game.js",content:`/**
 * Snake Game - Canvas Implementation
 * -----------------------------------
 * Arrow keys to move, eat food to grow, avoid walls and yourself.
 * Press Space to restart after game over.
 */

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const highEl = document.getElementById('high');
const messageEl = document.getElementById('message');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------
const CELL = 20;                        // size of each grid cell in px
const COLS = canvas.width / CELL;       // 20
const ROWS = canvas.height / CELL;      // 20
const TICK_MS = 100;                    // ms between game ticks

// Colours
const BG        = '#111827';
const SNAKE_CLR = '#22d3ee';
const HEAD_CLR  = '#06b6d4';
const FOOD_CLR  = '#f43f5e';
const GRID_CLR  = '#1a2233';

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------
let snake, dir, nextDir, food, score, highScore, running, gameOver, lastTick;

highScore = parseInt(localStorage.getItem('snake-high') || '0', 10);
highEl.textContent = 'Best: ' + highScore;

/** Initialise / reset the game state. */
function init() {
  const midY = Math.floor(ROWS / 2);
  snake = [
    { x: 5, y: midY },
    { x: 4, y: midY },
    { x: 3, y: midY },
  ];
  dir = { x: 1, y: 0 };
  nextDir = { ...dir };
  score = 0;
  running = false;
  gameOver = false;
  lastTick = 0;
  scoreEl.textContent = 'Score: 0';
  messageEl.textContent = 'Press any arrow key to start';
  placeFood();
  draw();
}

// ---------------------------------------------------------------------------
// Food placement
// ---------------------------------------------------------------------------

/** Place food on a random empty cell. */
function placeFood() {
  const occupied = new Set(snake.map(s => s.x + ',' + s.y));
  let pos;
  do {
    pos = {
      x: Math.floor(Math.random() * COLS),
      y: Math.floor(Math.random() * ROWS),
    };
  } while (occupied.has(pos.x + ',' + pos.y));
  food = pos;
}

// ---------------------------------------------------------------------------
// Input handling
// ---------------------------------------------------------------------------

const KEY_MAP = {
  ArrowUp:    { x:  0, y: -1 },
  ArrowDown:  { x:  0, y:  1 },
  ArrowLeft:  { x: -1, y:  0 },
  ArrowRight: { x:  1, y:  0 },
};

document.addEventListener('keydown', (e) => {
  // Restart on Space after game over
  if (e.code === 'Space' && gameOver) {
    init();
    return;
  }

  const newDir = KEY_MAP[e.key];
  if (!newDir) return;
  e.preventDefault();

  // Prevent reversing into yourself
  if (newDir.x === -dir.x && newDir.y === -dir.y) return;

  nextDir = newDir;

  // Start the game on first arrow press
  if (!running && !gameOver) {
    running = true;
    messageEl.textContent = '';
    lastTick = performance.now();
    requestAnimationFrame(loop);
  }
});

// ---------------------------------------------------------------------------
// Game loop
// ---------------------------------------------------------------------------

function loop(now) {
  if (!running) return;

  if (now - lastTick >= TICK_MS) {
    lastTick = now;
    update();
    draw();
  }

  if (running) {
    requestAnimationFrame(loop);
  }
}

/** Advance the game by one tick. */
function update() {
  dir = { ...nextDir };

  const head = {
    x: snake[0].x + dir.x,
    y: snake[0].y + dir.y,
  };

  // Wall collision
  if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) {
    return endGame();
  }

  // Self collision
  if (snake.some(s => s.x === head.x && s.y === head.y)) {
    return endGame();
  }

  snake.unshift(head);

  // Check food
  if (head.x === food.x && head.y === food.y) {
    score++;
    scoreEl.textContent = 'Score: ' + score;
    placeFood();
  } else {
    snake.pop();   // remove tail unless we just ate
  }
}

function endGame() {
  running = false;
  gameOver = true;
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('snake-high', String(highScore));
    highEl.textContent = 'Best: ' + highScore;
  }
  messageEl.textContent = 'Game Over! Press Space to restart';
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

function draw() {
  // Background
  ctx.fillStyle = BG;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Grid lines (subtle)
  ctx.strokeStyle = GRID_CLR;
  ctx.lineWidth = 0.5;
  for (let x = 0; x <= COLS; x++) {
    ctx.beginPath();
    ctx.moveTo(x * CELL, 0);
    ctx.lineTo(x * CELL, canvas.height);
    ctx.stroke();
  }
  for (let y = 0; y <= ROWS; y++) {
    ctx.beginPath();
    ctx.moveTo(0, y * CELL);
    ctx.lineTo(canvas.width, y * CELL);
    ctx.stroke();
  }

  // Food (pulsing glow)
  const pulse = 0.6 + 0.4 * Math.sin(Date.now() / 200);
  ctx.shadowColor = FOOD_CLR;
  ctx.shadowBlur = 12 * pulse;
  ctx.fillStyle = FOOD_CLR;
  ctx.beginPath();
  ctx.arc(
    food.x * CELL + CELL / 2,
    food.y * CELL + CELL / 2,
    CELL / 2 - 2,
    0,
    Math.PI * 2,
  );
  ctx.fill();
  ctx.shadowBlur = 0;

  // Snake body
  snake.forEach((seg, i) => {
    const isHead = i === 0;
    ctx.fillStyle = isHead ? HEAD_CLR : SNAKE_CLR;
    const pad = isHead ? 1 : 2;
    ctx.beginPath();
    ctx.roundRect(
      seg.x * CELL + pad,
      seg.y * CELL + pad,
      CELL - pad * 2,
      CELL - pad * 2,
      4,
    );
    ctx.fill();
  });
}

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

init();
