/**
 * React Quiz - Web Development Trivia
 * ====================================
 * 5 multiple-choice questions, progress bar, answer highlighting,
 * and a final score screen with restart.
 */

// ---------------------------------------------------------------------------
// Question data
// ---------------------------------------------------------------------------

interface Question {
  question: string
  options: string[]
  correct: number // index of the correct option
}

const QUESTIONS: Question[] = [
  {
    question: 'What does CSS stand for?',
    options: [
      'Creative Style Sheets',
      'Cascading Style Sheets',
      'Computer Style Sheets',
      'Colorful Style Sheets',
    ],
    correct: 1,
  },
  {
    question: 'Which hook is used for side effects in React?',
    options: ['useMemo', 'useRef', 'useEffect', 'useCallback'],
    correct: 2,
  },
  {
    question: 'What does the "DOM" stand for?',
    options: [
      'Document Object Model',
      'Digital Ordinance Map',
      'Document Oriented Markup',
      'Data Object Model',
    ],
    correct: 0,
  },
  {
    question: 'Which HTTP method is idempotent?',
    options: ['POST', 'PATCH', 'PUT', 'CONNECT'],
    correct: 2,
  },
  {
    question: 'What is the default position value in CSS?',
    options: ['relative', 'absolute', 'fixed', 'static'],
    correct: 3,
  },
]

// ---------------------------------------------------------------------------
// Styles (inline for portability)
// ---------------------------------------------------------------------------

const styles = {
  wrapper: {
    fontFamily: 'system-ui, -apple-system, sans-serif',
    minHeight: '100vh',
    display: 'grid',
    placeItems: 'center',
    background: '#0b0b12',
    color: '#e2e8f0',
    padding: '2rem',
  } as React.CSSProperties,
  card: {
    width: 'min(520px, 100%)',
    background: '#111827',
    borderRadius: '1.25rem',
    padding: '2rem 2.5rem',
    boxShadow: '0 24px 48px rgba(0,0,0,0.4)',
  } as React.CSSProperties,
  progressTrack: {
    height: 6,
    borderRadius: 3,
    background: '#1e293b',
    marginBottom: '1.5rem',
    overflow: 'hidden',
  } as React.CSSProperties,
  progressBar: (pct: number) =>
    ({
      height: '100%',
      width: pct + '%',
      background: 'linear-gradient(90deg, #6366f1, #8b5cf6)',
      borderRadius: 3,
      transition: 'width 0.4s ease',
    }) as React.CSSProperties,
  meta: {
    fontSize: '0.8rem',
    color: '#64748b',
    marginBottom: '0.5rem',
  } as React.CSSProperties,
  question: {
    fontSize: '1.15rem',
    fontWeight: 600,
    marginBottom: '1.25rem',
    lineHeight: 1.4,
  } as React.CSSProperties,
  option: (state: 'idle' | 'correct' | 'wrong' | 'dimmed') => {
    const base: React.CSSProperties = {
      display: 'block',
      width: '100%',
      textAlign: 'left' as const,
      padding: '0.85rem 1rem',
      marginBottom: '0.6rem',
      borderRadius: '0.75rem',
      border: '2px solid #1e293b',
      background: '#0f172a',
      color: '#e2e8f0',
      fontSize: '0.95rem',
      cursor: 'pointer',
      transition: 'all 0.2s',
    }
    if (state === 'correct') {
      base.border = '2px solid #22c55e'
      base.background = 'rgba(34,197,94,0.12)'
      base.color = '#4ade80'
    }
    if (state === 'wrong') {
      base.border = '2px solid #ef4444'
      base.background = 'rgba(239,68,68,0.12)'
      base.color = '#f87171'
    }
    if (state === 'dimmed') {
      base.opacity = 0.45
      base.cursor = 'default'
    }
    return base
  },
  nextBtn: {
    marginTop: '1rem',
    padding: '0.7rem 1.4rem',
    borderRadius: '0.75rem',
    border: 'none',
    background: '#6366f1',
    color: 'white',
    fontWeight: 600,
    fontSize: '0.95rem',
    cursor: 'pointer',
  } as React.CSSProperties,
  scoreCircle: {
    width: 120,
    height: 120,
    borderRadius: '50%',
    background: 'linear-gradient(135deg, #6366f1, #8b5cf6)',
    display: 'grid',
    placeItems: 'center',
    margin: '1rem auto',
  } as React.CSSProperties,
  scoreText: {
    fontSize: '2rem',
    fontWeight: 700,
  } as React.CSSProperties,
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function App() {
  const [current, setCurrent] = useState(0)
  const [selected, setSelected] = useState<number | null>(null)
  const [score, setScore] = useState(0)
  const [finished, setFinished] = useState(false)

  const total = QUESTIONS.length
  const q = QUESTIONS[current]
  const answered = selected !== null

  /** Handle clicking an answer option. */
  function handleSelect(idx: number) {
    if (answered) return
    setSelected(idx)
    if (idx === q.correct) setScore((s) => s + 1)
  }

  /** Advance to the next question or show final score. */
  function handleNext() {
    if (current + 1 >= total) {
      setFinished(true)
    } else {
      setCurrent((c) => c + 1)
      setSelected(null)
    }
  }

  /** Restart the quiz from scratch. */
  function handleRestart() {
    setCurrent(0)
    setSelected(null)
    setScore(0)
    setFinished(false)
  }

  /** Get the visual state for an option button. */
  function optionState(idx: number): 'idle' | 'correct' | 'wrong' | 'dimmed' {
    if (!answered) return 'idle'
    if (idx === q.correct) return 'correct'
    if (idx === selected) return 'wrong'
    return 'dimmed'
  }

  // -------------------------------------------------------------------------
  // Final score screen
  // -------------------------------------------------------------------------
  if (finished) {
    const pct = Math.round((score / total) * 100)
    const message =
      pct === 100
        ? 'Perfect score!'
        : pct >= 60
          ? 'Great job!'
          : 'Keep learning!'

    return (
      <div style={styles.wrapper}>
        <div style={{ ...styles.card, textAlign: 'center' as const }}>
          <h2 style={{ marginBottom: '0.25rem' }}>Quiz Complete</h2>
          <p style={{ color: '#94a3b8', marginBottom: '1rem' }}>{message}</p>
          <div style={styles.scoreCircle}>
            <span style={styles.scoreText}>
              {score}/{total}
            </span>
          </div>
          <p style={{ color: '#64748b', margin: '1rem 0' }}>
            You scored {pct}%
          </p>
          <button style={styles.nextBtn} onClick={handleRestart}>
            Play Again
          </button>
        </div>
      </div>
    )
  }

  // -------------------------------------------------------------------------
  // Question screen
  // -------------------------------------------------------------------------
  const progress = ((current + (answered ? 1 : 0)) / total) * 100

  return (
    <div style={styles.wrapper}>
      <div style={styles.card}>
        {/* Progress bar */}
        <div style={styles.progressTrack}>
          <div style={styles.progressBar(progress)} />
        </div>

        {/* Meta */}
        <p style={styles.meta}>
          Question {current + 1} of {total}
        </p>

        {/* Question text */}
        <h2 style={styles.question}>{q.question}</h2>

        {/* Options */}
        {q.options.map((opt, idx) => (
          <button
            key={idx}
            style={styles.option(optionState(idx))}
            onClick={() => handleSelect(idx)}
          >
            {opt}
          </button>
        ))}

        {/* Next / Finish button */}
        {answered && (
          <button style={styles.nextBtn} onClick={handleNext}>
            {current + 1 >= total ? 'See Results' : 'Next Question'}
          </button>
        )}
      </div>
    </div>
  )
}
